"""Date-window membership for the date_window fixture."""

from __future__ import annotations

import datetime


def _parse_date(date_str: str) -> datetime.date:
    """Parse a date string in strict YYYY-MM-DD format, raising ValueError if invalid."""
    if not isinstance(date_str, str):
        raise ValueError(f"Expected string, got {type(date_str)}")
    # Check strict format: must be exactly YYYY-MM-DD
    if len(date_str) != 10:
        raise ValueError(f"Invalid date format: {date_str!r}")
    if date_str[4] != '-' or date_str[7] != '-':
        raise ValueError(f"Invalid date format: {date_str!r}")
    year_str = date_str[0:4]
    month_str = date_str[5:7]
    day_str = date_str[8:10]
    # Ensure all parts are digits
    if not (year_str.isdigit() and month_str.isdigit() and day_str.isdigit()):
        raise ValueError(f"Invalid date format: {date_str!r}")
    # Ensure zero-padding by checking that parsed ints match the string representation
    year = int(year_str)
    month = int(month_str)
    day = int(day_str)
    # Validate by constructing a date object (raises ValueError for impossible dates)
    try:
        d = datetime.date(year, month, day)
    except ValueError:
        raise ValueError(f"Invalid calendar date: {date_str!r}")
    # Check that the formatted date matches the input (catches missing zero-padding)
    if d.strftime("%Y-%m-%d") != date_str:
        raise ValueError(f"Invalid date format (non-canonical): {date_str!r}")
    return d


def in_any_window(target_date: str, windows: list[tuple[str, str]]) -> bool:
    """Return whether target_date falls inside any date window."""
    # Parse and validate the target date first
    target = _parse_date(target_date)

    # Parse and validate all windows before checking membership
    parsed_windows = []
    for start_str, end_str in windows:
        start = _parse_date(start_str)
        end = _parse_date(end_str)
        if start > end:
            raise ValueError(
                f"Window start {start_str!r} is after end {end_str!r}"
            )
        parsed_windows.append((start, end))

    # Check membership in any window (inclusive boundaries)
    for start, end in parsed_windows:
        if start <= target <= end:
            return True

    return False
